inputs = ['cbu', 'hwzudu', 'ihyeuk', 'dcx', 'wxdux']
outputs = ['cijgu', 'hwzudu', 'ihyeuk', 'dchzu', 'whzudzh']

# Let me check if there's a consistent pattern of replacements
# I'll make a table of what characters change
changes = {}

for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"{inp} -> {outp}")

    # Find differing positions
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
            if inp[j] not in changes:
                changes[inp[j]] = outp[j]

    # Check for additions/removals
    if len(inp) < len(outp):
        print(f"  Added chars: {outp[len(inp):]}")
    elif len(inp) > len(outp):
        print(f"  Removed chars: {inp[len(outp):]}")

print("\nCharacter changes identified:", changes)

